def get_client_ip(client_address: str) -> str:
    """Extract client IP from the Full-Header or X-Forwarded-For headers."""
    # Try X-Forwarded-For (first IP in the list)
    for forwarded in client_address.split(", "):
        ip = forwarded.strip()
        if ip:
            return ip
    # Fallback to the real IP (client_address is the remote address)
    return client_address

